assignments.value:
={{
(() => {
  const text =
    $json.document?.pageContent ||
    $json.pageContent ||
    $json.text ||
    $json.content ||
    '';

  const nextPolicy = text.indexOf('4. Payroll corrections');

  return nextPolicy >= 0
    ? text.slice(0, nextPolicy).trim()
    : text.trim();
})()
}}

={{
(() => {
  const text = String(
    $json.document?.pageContent ||
    $json.pageContent ||
    $json.text ||
    $json.content ||
    ''
  );

  if (/3\.1[ \t]+Annual entitlement/i.test(text)) {
    return 'POL-LEAVE-02';
  }

  return (text.match(/POL-[A-Z]+-\d+/i) || [''])[0].toUpperCase();
})()
}}
